"""
app.py  -  Flask REST API + Presentation-style Web Frontend
Trains models on first startup (no .pkl files needed).
"""
from flask import Flask, request, jsonify, render_template_string
import numpy as np, pandas as pd, os
from sklearn.ensemble import RandomForestClassifier, RandomForestRegressor
from sklearn.preprocessing import LabelEncoder, StandardScaler
from sklearn.model_selection import train_test_split

app = Flask(__name__)

CONTRACT_MAP      = {"Month-to-month":0,"One year":1,"Two year":2}
PAYMENT_MAP       = {"Bank transfer":0,"Credit card":1,"Electronic check":2,"Mailed check":3}
PAPERLESS_MAP     = {"No":0,"Yes":1}
LOCATION_MAP      = {"Rural":0,"Suburb":1,"Urban":2}
PROPERTY_TYPE_MAP = {"Apartment":0,"House":1,"Villa":2}

def train_models():
    BASE = os.path.dirname(os.path.abspath(__file__))
    def find(name):
        for p in [os.path.join(BASE,"data",name), os.path.join(BASE,name)]:
            if os.path.exists(p): return p
        raise FileNotFoundError(f"{name} not found. Put it in the data/ folder.")
    churn = pd.read_csv(find("customer_churn.csv"))
    le = LabelEncoder()
    for col in ["Contract","PaymentMethod","PaperlessBilling"]:
        churn[f"{col}_enc"] = le.fit_transform(churn[col])
    FEAT_C = ["Tenure","MonthlyCharges","TotalCharges","Contract_enc","PaymentMethod_enc","PaperlessBilling_enc","SeniorCitizen"]
    X_c,y_c = churn[FEAT_C],churn["Churn"]
    X_tr,X_te,y_tr,_ = train_test_split(X_c,y_c,test_size=0.2,random_state=42,stratify=y_c)
    sc = StandardScaler(); sc.fit(X_tr)
    clf = RandomForestClassifier(n_estimators=100,random_state=42)
    clf.fit(sc.transform(X_tr),y_tr)
    house = pd.read_csv(find("house_prices.csv"))
    house["Location_enc"] = LabelEncoder().fit_transform(house["Location"])
    house["PropertyType_enc"] = LabelEncoder().fit_transform(house["Property_Type"])
    FEAT_H = ["Area","Bedrooms","Bathrooms","Age","Location_enc","PropertyType_enc"]
    X_h,y_h = house[FEAT_H],house["Price"]
    X_htr,_,y_htr,_ = train_test_split(X_h,y_h,test_size=0.2,random_state=42)
    reg = RandomForestRegressor(n_estimators=100,random_state=42)
    reg.fit(X_htr,y_htr)
    print("Models trained."); return clf,sc,reg

churn_model,scaler,house_model = train_models()

